import{_ as e,c as n,o,ah as a}from"./chunks/framework.DE7iKuik.js";const m=JSON.parse('{"title":"版本限制","frontmatter":{"title":"版本限制","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/versions.html","lastUpdated":"2026-01-20","tags":[],"link":"/docs/composer/官方文章/versions","layout":"doc","sidebar":true,"aside":true,"prev":{"text":"分支别名","link":"/docs/composer/官方文章/aliases"},"next":{"text":"自动加载器优化","link":"/docs/composer/官方文章/optimization"}},"headers":[],"params":{"pkg":"composer/官方文章/versions","sidebar":[{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]}],"versions":[]},"relativePath":"docs/composer/官方文章/versions.md","filePath":"docs/[pkg].md"}'),s={name:"docs/composer/官方文章/versions.md"};function c(d,l,t,r,i,p){return o(),n("div",null,[...l[0]||(l[0]=[a(`<h1 id="版本和约束" tabindex="-1">版本和约束 <a class="header-anchor" href="#版本和约束" aria-label="Permalink to “版本和约束”">​</a></h1><h2 id="composer-版本和-vcs-版本" tabindex="-1">Composer 版本和 VCS 版本 <a class="header-anchor" href="#composer-版本和-vcs-版本" aria-label="Permalink to “Composer 版本和 VCS 版本”">​</a></h2><p>Composer 很大程度上依赖于像 Git 这样的版本控制系统，所以说『版本』可能有点含糊不清。在版本控制系统的意义上，『版本』是包含特定数据的特定文件集。在 Git 术语中，它可以是 ref 或者某个特定提交，可以由分支 HEAD 或 tag 表示。当您在 VCS 中签出该版本时 - 例如，标记 <code>v1.1</code> 或提交 <code>e35fa0d</code> 等等 ，您需要一组已知的文件，并且您总是会获得相同的文件。</p><p>在 Composer 中对版本的定义是 —— 当我们引入一个包的时候，在 require 后面的字符串（例如 <code>~1.1</code> 或  <code>1.2.*</code>）实际上是对这个包的版本约束。 Composer 使用版本约束来确定应该从 VCS 中检出的文件集（或者只是验证在 <code>composer.json</code> 中具有 <code>version</code> 规范的 Statically-Maintained 库是否可以使用）。</p><h2 id="vcs-标签-和-分支" tabindex="-1">VCS 标签 和 分支 <a class="header-anchor" href="#vcs-标签-和-分支" aria-label="Permalink to “VCS 标签 和 分支”">​</a></h2><p><em>以下的讨论中，我们假设使用如下列出的 library 仓库:</em></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/my-library$ git branch</span></span>
<span class="line"><span>v1</span></span>
<span class="line"><span>v2</span></span>
<span class="line"><span>my-feature</span></span>
<span class="line"><span>nother-feature</span></span>
<span class="line"><span></span></span>
<span class="line"><span>~/my-library$ git tag</span></span>
<span class="line"><span>v1.0</span></span>
<span class="line"><span>v1.0.1</span></span>
<span class="line"><span>v1.0.2</span></span>
<span class="line"><span>v1.1-BETA</span></span>
<span class="line"><span>v1.1-RC1</span></span>
<span class="line"><span>v1.1-RC2</span></span>
<span class="line"><span>v1.1</span></span>
<span class="line"><span>v1.1.1</span></span>
<span class="line"><span>v2.0-BETA</span></span>
<span class="line"><span>v2.0-RC1</span></span>
<span class="line"><span>v2.0</span></span>
<span class="line"><span>v2.0.1</span></span>
<span class="line"><span>v2.0.2</span></span></code></pre></div><h3 id="标签" tabindex="-1">标签 <a class="header-anchor" href="#标签" aria-label="Permalink to “标签”">​</a></h3><p>通常情况, Composer 使用标签来处理版本控制 (标签不同与分支 -- 如果不明白什么是分支，请阅读 <a href="https://en.wikipedia.org/wiki/Version_control#Common_vocabulary" target="_blank" rel="noreferrer">version control systems</a>). 当你写版本限制条件时，Composer 所引用的是一个确切的标签 (例如， <code>1.1</code>) 或者一个合法的标签范围 (例如， <code>&gt;=1.1 &lt;2.0</code>， 或者 <code>~4.0</code>)。 当 Composer 解析这些版本限制时， 它首先向 VCS 索取所有可用的标签的列表， 然后基于这个列表创建一个可用版本号的内部列表。如上边的例子， Composer 的内部列表包含了版本 <code>1.0</code>， <code>1.0.1</code>， <code>1.0.2</code>， <code>1.1</code> 的 beta 版本，  <code>1.1</code> 的第一和第二候选发行版本， <code>1.1</code> 的最终发行版本, 等等.... (注意， Composer 会自动去掉标签名称中的 &#39;v&#39; 前缀来得到一个最终可用的版本号。)</p><p>当 Composer 从 VCS 得到一个完整的可用版本列表后， 它会找到一个与你项目中的版本限制所匹配的最高的版本 （项目中其他的一些依赖包包也许会要求一些更特定的版本，比项目所要求的更低或更高， 所以 Composer 选择的版本不一定总是最高的） 接着 Composer 会下载一个标签所对应的 zip 包并解压缩在 <code>vendor</code> 目录中相应的位置。</p><h3 id="分支" tabindex="-1">分支 <a class="header-anchor" href="#分支" aria-label="Permalink to “分支”">​</a></h3><p>如果希望 Composer 签出分支而不是标记，则需要使用特殊的<code>dev-*</code>前缀 (有时是后缀,参考下面) 将其指向分支。如果您正在签出分支，则假定您希望在分支上<em>工作</em>，而 Composer 实际上将 Repo 复制到<code>vendor</code>目录中的正确位置。对于标签，它只复制正确的文件，而不实际克隆repo。(您可以使用--prefer-source和--prefer-dist修改此行为，请参阅<a href="./../03-cli#install">安装选项</a>.)</p><p>在上面的示例中，如果要签出 <code>my-feature</code> 分支，则可以将 <code>dev-my-feature</code> 指定为 <code>require</code> 子句中的版本约束。这将导致 Composer 将 <code>my-library</code> 库克隆到我的<code>vendor</code> 目录中，并签出 <code>my-feature</code> 分支。</p><p>当分支名称看起来像版本时，我们必须为 composer 澄清，我们正在尝试签出分支而不是标记。在上面的示例中，我们有两个版本分支: <code>v1</code> 和 <code>v2</code>。要使 Composer 签出这些分支之一，必须指定一个类似于以下内容的版本约束: <code>v1.x-dev</code>。<code>.x</code>是一个任意字符串，Composer 需要告诉它，我们谈论的是 <code>v1</code> 分支，而不是一个 <code>v1</code> 标记 (或者，你可以只命名分支<code>v1.x</code>而不是 <code>v1</code>)。对于具有类似版本名称的分支 (在本例中为 <code>v1</code>)，您将追加<code>-dev</code>为后缀，而不是使用<code>dev-</code>作为前缀。</p><h3 id="最小稳定性" tabindex="-1">最小稳定性 <a class="header-anchor" href="#最小稳定性" aria-label="Permalink to “最小稳定性”">​</a></h3><p>还有一件事会影响从库的 VCS 中签出哪些文件并添加到项目中: Composer 允许您指定稳定约束以限制哪些标记被认为是有效的。在上面的示例中，请注意，库在最终正式发布之前发布了版本<code>1.1</code> 的 beta 版和两个候选版本。要在运行<code>composer install</code>或<code>composer update</code>时接收这些版本，我们必须显式告诉 Composer，我们可以使用发布候选版本和 beta 版 (如果我们想要的话)。这可以在<code>composer.json</code>中使用项目范围内的<code>minimum-stability</code>值来完成或在版本约束中使用 &quot;stability flags&quot;。在 <a href="./../04-schema#minimum-stability">架构 页</a>上阅读更多内容。</p><h2 id="编写版本约束" tabindex="-1">编写版本约束 <a class="header-anchor" href="#编写版本约束" aria-label="Permalink to “编写版本约束”">​</a></h2><p>现在，您已经知道了Composer是如何看待版本的，让我们来谈谈如何为项目依赖项指定版本约束。</p><h3 id="精确的版本约束" tabindex="-1">精确的版本约束 <a class="header-anchor" href="#精确的版本约束" aria-label="Permalink to “精确的版本约束”">​</a></h3><p>您可以指定包的确切版本。这将告诉Composer仅安装此版本。如果其他依赖项需要不同的版本，则规划求解最终将失败并中止任何安装或更新过程。</p><p>例如: <code>1.0.2</code></p><h3 id="版本范围" tabindex="-1">版本范围 <a class="header-anchor" href="#版本范围" aria-label="Permalink to “版本范围”">​</a></h3><p>通过使用比较运算符，可以指定有效版本的范围。有效的运算符是<code>&gt;</code>，<code>&gt;=</code>，<code>&lt;</code>，<code>&lt;=</code>，<code>!=</code>。</p><p>您可以定义多个范围。用空格 (<code> </code>) 或逗号(<code>,</code>) 分隔的范围将被视为<strong>逻辑 AND</strong>。双管 (<code>||</code>) 将被视为<strong>逻辑 OR</strong>。且优先级高于OR。</p><blockquote><p><strong>注意:</strong> 使用无限制范围时要小心，因为您可能会意外地安装破坏向后兼容性的版本。为了安全请考虑使用<a href="#caret-version-range">脱字符</a>运算符。</p></blockquote><p>例如：</p><ul><li><code>&gt;=1.0</code></li><li><code>&gt;=1.0 &lt;2.0</code></li><li><code>&gt;=1.0 &lt;1.1 || &gt;=1.2</code></li></ul><h3 id="带连字符的版本范围" tabindex="-1">带连字符的版本范围 ( - ) <a class="header-anchor" href="#带连字符的版本范围" aria-label="Permalink to “带连字符的版本范围 ( - )”">​</a></h3><p>包含了一系列的版本。通配符的右边限制了版本的最大范围。 举个例子 <code>1.0 - 2.0</code> 等价于 <code>&gt;=1.0.0 &lt;2.1</code> ，因为 <code>2.0</code> 等价于 <code>2.0.*</code>。而 <code>1.0.0 - 2.1.0</code> 等价于 <code>&gt;=1.0.0 &lt;=2.1.0</code>。</p><p>举例: <code>1.0 - 2.0</code></p><h3 id="带通配符的版本范围" tabindex="-1">带通配符的版本范围 (.*) <a class="header-anchor" href="#带通配符的版本范围" aria-label="Permalink to “带通配符的版本范围 (.*)”">​</a></h3><p>你可以使用 <code>*</code> 通配符。 <code>1.0.*</code> 等价于<code>&gt;=1.0 &lt;1.1</code>。</p><p>举例: <code>1.0.*</code></p><h2 id="下一个重要的发布运算符" tabindex="-1">下一个重要的发布运算符 <a class="header-anchor" href="#下一个重要的发布运算符" aria-label="Permalink to “下一个重要的发布运算符”">​</a></h2><h3 id="波形符版本范围" tabindex="-1">波形符版本范围 (~) <a class="header-anchor" href="#波形符版本范围" aria-label="Permalink to “波形符版本范围 (~)”">​</a></h3><p><code>~</code> 运算符最好用示例解释：<code>~1.2</code> 等价于<code>&gt;=1.2 &lt;2.0.0</code>，而 <code>~1.2.3</code>等价于 <code>&gt;=1.2.3 &lt;1.3.0</code>。正如您所看到的，它对于尊重 <a href="https://semver.org/" target="_blank" rel="noreferrer">语义版本控制</a>的项目来说是非常有用的。通常的用法是标记您所依赖的最小次要版本，如 <code>~1.2</code> (允许任何内容，但不包括 2.0)。因为理论上应该没有向后兼容性破坏直到 2.0，它会运行良好。另一种看待它的方法是使用<code>~</code> 指定一个最小版本，但允许指定的最后一个数字增长。</p><p>例如：<code>~1.2</code></p><blockquote><p><strong>注意:</strong> 注意：虽然 <code>2.0-beta.1</code> 是在<code>2.0</code>之前，但版本约束，如 <code>~1.2</code> 不会安装它。正如上面所说的<code>~1.2</code>只意味着<code>.2</code> 可以改变，但<code>1.</code>部分是固定的。</p></blockquote><blockquote><p><strong>注意:</strong> <code>~</code>运算符对其主要发行号的行为有例外。这意味着，<code>~1</code>与<code>~1.0</code> 是相同的，因为它不会允许主数字增加以试图保持向后兼容性。</p></blockquote><h3 id="脱字符版本范围" tabindex="-1">脱字符版本范围 (^) <a class="header-anchor" href="#脱字符版本范围" aria-label="Permalink to “脱字符版本范围 (^)”">​</a></h3><p><code>^</code>运算符的行为非常相似，但它更接近语义版本控制，并且始终允许不中断的更新。例如 <code>^1.2.3</code> 等效于<code>&gt;=1.2.3 &lt;2.0.0</code> 因为直到 2.0 的版本都不应该破坏向后兼容性。 pre-1.0 版本也考虑安全性并把<code>^0.3</code>当作为 <code>&gt;=0.3.0 &lt;0.4.0</code>。</p><p>这是推荐的运算符，在编写库代码时具有最大的互操作性。</p><p>例如：<code>^1.2.3</code></p><h2 id="稳定性约束" tabindex="-1">稳定性约束 <a class="header-anchor" href="#稳定性约束" aria-label="Permalink to “稳定性约束”">​</a></h2><p>如果您使用的约束没有显式定义稳定性, 则根据所使用的运算符, Composer将在内部默认为 <code>-dev</code> 或 <code>-stable</code>。这种情况是透明的。</p><p>如果希望在比较中只显式考虑稳定版本, 请添加<code>-stable</code>后缀。</p><p>例如:</p><table tabindex="0"><thead><tr><th>约束</th><th>内部</th></tr></thead><tbody><tr><td><code>1.2.3</code></td><td><code>=1.2.3.0-stable</code></td></tr><tr><td><code>&gt;1.2</code></td><td><code>&gt;1.2.0.0-stable</code></td></tr><tr><td><code>&gt;=1.2</code></td><td><code>&gt;=1.2.0.0-dev</code></td></tr><tr><td><code>&gt;=1.2-stable</code></td><td><code>&gt;=1.2.0.0-stable</code></td></tr><tr><td><code>&lt;1.3</code></td><td><code>&lt;1.3.0.0-dev</code></td></tr><tr><td><code>&lt;=1.3</code></td><td><code>&lt;=1.3.0.0-stable</code></td></tr><tr><td><code>1 - 2</code></td><td><code>&gt;=1.0.0.0-dev &lt;3.0.0.0-dev</code></td></tr><tr><td><code>~1.3</code></td><td><code>&gt;=1.3.0.0-dev &lt;2.0.0.0-dev</code></td></tr><tr><td><code>1.4.*</code></td><td><code>&gt;=1.4.0.0-dev &lt;1.5.0.0-dev</code></td></tr></tbody></table><h2 id="为了允许不同的稳定性-而不是在约束级别强制执行它们-您可以使用诸如-stability-例如-dev-之类的稳定性标志-让composer知道给定的软件包可以在不同的稳定性下安装-而不是默认的最小稳定性设置-所有可用的稳定标志都列在架构页的-最小稳定-部分中。总结" tabindex="-1">为了允许不同的稳定性, 而不是在约束级别强制执行它们, 您可以使用诸如 <code>@&lt;stability&gt;</code> (例如 <code>@dev</code>) 之类的<a href="./../04-schema#package-links">稳定性标志</a>, 让composer知道给定的软件包可以在不同的稳定性下安装, 而不是默认的最小稳定性设置.所有可用的稳定标志都列在<a href="./../04-schema#minimum-stability">架构页</a>的 &quot;最小稳定&quot; 部分中。 总结 <a class="header-anchor" href="#为了允许不同的稳定性-而不是在约束级别强制执行它们-您可以使用诸如-stability-例如-dev-之类的稳定性标志-让composer知道给定的软件包可以在不同的稳定性下安装-而不是默认的最小稳定性设置-所有可用的稳定标志都列在架构页的-最小稳定-部分中。总结" aria-label="Permalink to “为了允许不同的稳定性, 而不是在约束级别强制执行它们, 您可以使用诸如 @&lt;stability&gt; (例如 @dev) 之类的稳定性标志, 让composer知道给定的软件包可以在不同的稳定性下安装, 而不是默认的最小稳定性设置.所有可用的稳定标志都列在架构页的 &quot;最小稳定&quot; 部分中。总结”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;require&quot;: {</span></span>
<span class="line"><span>    &quot;vendor/package&quot;: &quot;1.3.2&quot;,</span><span> // exactly 1.3.2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // &gt;, &lt;, &gt;=, &lt;= | specify upper / lower bounds</span></span>
<span class="line"><span>    &quot;vendor/package&quot;: &quot;&gt;=1.3.2&quot;,</span><span> // anything above or equal to 1.3.2</span></span>
<span class="line"><span>    &quot;vendor/package&quot;: &quot;&lt;1.3.2&quot;,</span><span> // anything below 1.3.2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // * | wildcard</span></span>
<span class="line"><span>    &quot;vendor/package&quot;: &quot;1.3.*&quot;,</span><span> // &gt;=1.3.0 &lt;1.4.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // ~ | allows last digit specified to go up</span></span>
<span class="line"><span>    &quot;vendor/package&quot;: &quot;~1.3.2&quot;,</span><span> // &gt;=1.3.2 &lt;1.4.0</span></span>
<span class="line"><span>    &quot;vendor/package&quot;: &quot;~1.3&quot;,</span><span> // &gt;=1.3.0 &lt;2.0.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    // ^ | doesn&#39;t allow breaking changes (major version fixed - following semver)</span></span>
<span class="line"><span>    &quot;vendor/package&quot;: &quot;^1.3.2&quot;,</span><span> // &gt;=1.3.2 &lt;2.0.0</span></span>
<span class="line"><span>    &quot;vendor/package&quot;: &quot;^0.3.2&quot;,</span><span> // &gt;=0.3.2 &lt;0.4.0</span><span> // except if major version is 0</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="检测版本限制" tabindex="-1">检测版本限制 <a class="header-anchor" href="#检测版本限制" aria-label="Permalink to “检测版本限制”">​</a></h2><p>你可以使用 <a href="https://semver.mwl.be/" target="_blank" rel="noreferrer">semver.mwl.be</a> 检测版本限制。填写包名字，它将自动添加默认版本限制信息，Composer 可以将其添加到 <code>composer.json</code> 文件。你可以调整版本限制信息，这个工具可以将对应的所有分支高亮。</p>`,52)])])}const h=e(s,[["render",c]]);export{m as __pageData,h as default};
